import{_ as t,o,c as a,a2 as n}from"./chunks/framework.DaAAbehN.js";const p=JSON.parse('{"title":"Lesson 4: Preparation","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-2/lesson-4.md","filePath":"en/modules/module-2/lesson-4.md"}'),r={name:"en/modules/module-2/lesson-4.md"};function s(i,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="lesson-4-preparation" tabindex="-1">Lesson 4: Preparation <a class="header-anchor" href="#lesson-4-preparation" aria-label="Permalink to &quot;Lesson 4: Preparation&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Understand the accounts, devices, and network environment needed before using Codex ⏱️ <strong>Estimated Time</strong>: 10 minutes 🎯 <strong>Teaching Rhythm</strong>: Explanation-focused</p></blockquote><hr><h2 id="i-what-do-you-need" tabindex="-1">I. What Do You Need? <a class="header-anchor" href="#i-what-do-you-need" aria-label="Permalink to &quot;I. What Do You Need?&quot;">​</a></h2><h3 id="_1-a-chatgpt-account" tabindex="-1">1. A ChatGPT Account <a class="header-anchor" href="#_1-a-chatgpt-account" aria-label="Permalink to &quot;1. A ChatGPT Account&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Plan</th><th>Price</th><th>Quota</th><th>Recommendation</th></tr></thead><tbody><tr><td>Free</td><td>$0</td><td>Limited</td><td>Can try it out, but not enough for serious use</td></tr><tr><td>Plus</td><td>$20/month</td><td>Generous</td><td>✅ Recommended for beginners</td></tr><tr><td>Pro</td><td>$200/month</td><td>Extensive</td><td>Heavy users</td></tr></tbody></table><blockquote><p>💡 <strong>Suggestion</strong>: If this is your first time using Codex, start with the Plus plan for a week. If you find it useful, consider upgrading to Pro.</p></blockquote><h3 id="_2-a-computer" tabindex="-1">2. A Computer <a class="header-anchor" href="#_2-a-computer" aria-label="Permalink to &quot;2. A Computer&quot;">​</a></h3><ul><li><strong>macOS</strong>: macOS 12.0 or later</li><li><strong>Windows</strong>: Windows 10 or later</li><li><strong>Chromebook</strong>: Chrome OS supported</li></ul><h3 id="_3-a-stable-internet-connection" tabindex="-1">3. A Stable Internet Connection <a class="header-anchor" href="#_3-a-stable-internet-connection" aria-label="Permalink to &quot;3. A Stable Internet Connection&quot;">​</a></h3><p>Codex needs real-time connectivity to communicate with AI servers. A broadband connection of 50Mbps or above is recommended.</p><hr><h2 id="ii-four-ways-to-use-codex" tabindex="-1">II. Four Ways to Use Codex <a class="header-anchor" href="#ii-four-ways-to-use-codex" aria-label="Permalink to &quot;II. Four Ways to Use Codex&quot;">​</a></h2><h3 id="method-1-desktop-app-most-recommended-for-beginners" tabindex="-1">Method 1: Desktop App (Most Recommended for Beginners) <a class="header-anchor" href="#method-1-desktop-app-most-recommended-for-beginners" aria-label="Permalink to &quot;Method 1: Desktop App (Most Recommended for Beginners)&quot;">​</a></h3><p><img src="https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=800" alt="Codex Desktop App"></p><ul><li>Visual interface, operations are clear at a glance</li><li>Drag and drop files directly into the workspace</li><li>Watch the AI&#39;s execution process in real time</li><li>Intuitive permission management</li></ul><p><strong>Best for</strong>: All users, especially beginners with zero programming experience.</p><h3 id="method-2-chatgpt-web-version" tabindex="-1">Method 2: ChatGPT Web Version <a class="header-anchor" href="#method-2-chatgpt-web-version" aria-label="Permalink to &quot;Method 2: ChatGPT Web Version&quot;">​</a></h3><p>Switch to &quot;Advanced Search&quot; or &quot;Code Interpreter&quot; mode on <a href="https://chatgpt.com" target="_blank" rel="noreferrer">chatgpt.com</a>.</p><ul><li>No software installation required</li><li>Available anytime, anywhere</li><li>Features are relatively basic</li></ul><p><strong>Best for</strong>: Occasional users who don&#39;t want to install software.</p><h3 id="method-3-command-line-cli" tabindex="-1">Method 3: Command Line (CLI) <a class="header-anchor" href="#method-3-command-line-cli" aria-label="Permalink to &quot;Method 3: Command Line (CLI)&quot;">​</a></h3><p>Use Codex directly through the terminal, suitable for users familiar with command lines.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Help me write a sorting program&quot;</span></span></code></pre></div><p><strong>Best for</strong>: Developers, operations staff.</p><h3 id="method-4-vs-code-extension" tabindex="-1">Method 4: VS Code Extension <a class="header-anchor" href="#method-4-vs-code-extension" aria-label="Permalink to &quot;Method 4: VS Code Extension&quot;">​</a></h3><p>Install the Codex extension in VS Code and use it directly in the editor.</p><p><strong>Best for</strong>: Developers already using VS Code.</p><hr><h2 id="iii-in-lesson-practice-tasks" tabindex="-1">III. In-Lesson Practice Tasks <a class="header-anchor" href="#iii-in-lesson-practice-tasks" aria-label="Permalink to &quot;III. In-Lesson Practice Tasks&quot;">​</a></h2><ol><li>Log into your ChatGPT account</li><li>Confirm which plan you&#39;re currently using (Free / Plus / Pro)</li><li>Try opening ChatGPT&#39;s &quot;Advanced Search&quot; mode</li><li>Type: &quot;Hello, please introduce yourself.&quot;</li></ol><blockquote><p>💡 <strong>Tip</strong>: This step is just to help you get familiar with the interface. You don&#39;t need to understand too many technical details.</p></blockquote><hr><h2 id="iv-summary" tabindex="-1">IV. Summary <a class="header-anchor" href="#iv-summary" aria-label="Permalink to &quot;IV. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knowledge Point</th><th>Core Content</th></tr></thead><tbody><tr><td>Account requirement</td><td>ChatGPT account (Free works, Plus recommended)</td></tr><tr><td>Device requirement</td><td>macOS 12+ or Windows 10+</td></tr><tr><td>Four usage methods</td><td>Desktop App (recommended), Web, CLI, VS Code extension</td></tr><tr><td>Best for beginners</td><td>Desktop App — simple and intuitive</td></tr></tbody></table><hr><h2 id="v-next-step" tabindex="-1">V. Next Step <a class="header-anchor" href="#v-next-step" aria-label="Permalink to &quot;V. Next Step&quot;">​</a></h2><p><a href="./lesson-5.html">→ Lesson 5: Installing Codex Desktop App</a></p>',38)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
